#include "yuzu/game_companion_catalog.h"

#include <array>

namespace GameCompanion {
namespace {

constexpr std::string_view Places = "https://zelda.mtwildwood.net/en-gb/places/";
constexpr std::string_view Dungeons = "https://zelda.mtwildwood.net/en-gb/dungeons/";

constexpr std::array Entries{
    Entry{"castle_town", Kind::Place, {"Hyrule Castle Town", "Ciudadela de Hyrule"},
          {"The busy market town outside Hyrule Castle.", "El bullicioso mercado junto al castillo de Hyrule."},
          {"Shops, games and townspeople make this the kingdom's social center during Link's childhood. It connects the field to the royal grounds and the Temple of Time. Returning as an adult shows one of the story's sharpest changes to Hyrule.",
           "Tiendas, juegos y vecinos la convierten en el centro social del reino durante la infancia de Link. Une la pradera con el recinto real y el Templo del Tiempo. Regresar como adulto revela uno de los cambios más bruscos de Hyrule."},
          Places, false},
    Entry{"temple_of_time", Kind::Place, {"Temple of Time", "Templo del Tiempo"},
          {"A sacred building at the heart of Link's time-travel story.",
           "Edificio sagrado en el centro de la historia de viajes temporales de Link."},
          {"It stands near the castle town and protects the way to the Master Sword. Its doors connect the Spiritual Stones, the Ocarina of Time and the kingdom's older sacred history. Later, returning here lets Link move between two periods of his adventure.",
           "Se alza cerca de la ciudadela y protege el camino a la Espada Maestra. Sus puertas vinculan las Piedras Espirituales, la Ocarina del Tiempo y la historia sagrada del reino. Más adelante, volver aquí permite a Link viajar entre dos periodos de su aventura."},
          Places, false},
    Entry{"goron_city", Kind::Place, {"Goron City", "Ciudad Goron"},
          {"The Gorons' home inside Death Mountain.", "El hogar de los Goron dentro de la Montaña de la Muerte."},
          {"A network of rocky levels where Darunia leads his people. The settlement depends on the nearby cavern, so trouble there becomes a problem for every Goron. Exploring its vertical paths and talking to residents reveals how this mountain society works.",
           "Es una red de niveles rocosos donde Darunia dirige a su pueblo. El asentamiento depende de la caverna próxima; si allí hay problemas, todos los Goron los sufren. Recorrer sus caminos verticales y hablar con sus vecinos muestra cómo vive esta sociedad de montaña."},
          Places, false},
    Entry{"gerudo_fortress", Kind::Place, {"Gerudo Fortress", "Fortaleza Gerudo"},
          {"A guarded stronghold of the Gerudo people.", "Bastión vigilado del pueblo gerudo."},
          {"It lies beyond Gerudo Valley and is difficult for an outsider to enter unnoticed. Patrols, cells and trials make the fortress an infiltration challenge as well as a settlement. Its people have their own views of Ganondorf; they are not simply interchangeable with him.",
           "Está más allá del Valle Gerudo y a un forastero le cuesta entrar sin ser visto. Patrullas, celdas y pruebas convierten la fortaleza en un reto de infiltración además de un asentamiento. Sus habitantes tienen opiniones propias sobre Ganondorf; no son una extensión de él."},  // codespell:ignore ser
          Places, false},
    Entry{"sacred_grove", Kind::Place, {"Sacred Forest Meadow", "Pradera Sagrada del Bosque"},
          {"A secluded clearing reached through the Lost Woods.",
           "Claro apartado al que se llega atravesando el Bosque Perdido."},
          {"The winding approach rewards listening and remembering the right path. Saria is closely tied to this place, and its atmosphere shifts as Link grows older. Later, Moblins guard the route toward the Forest Temple.",
           "El acceso sinuoso premia escuchar y recordar la ruta correcta. Saria está muy ligada a este lugar, cuya atmósfera cambia cuando Link crece. Más adelante, los Moblins vigilan el camino hacia el Templo del Bosque."},
          Places, false},
    Entry{"hyrule_castle", Kind::Place, {"Hyrule Castle", "Castillo de Hyrule"},
          {"The royal family's seat, north of the market town.",
           "Sede de la familia real, al norte de la ciudadela."},
          {"Its guarded grounds are where young Link tries to reach Zelda without attracting attention. The castle is also where Ganondorf's ambitions become a direct threat to the kingdom. The area carries political weight even before Link understands the full plot.",
           "Sus terrenos vigilados son el lugar donde Link niño intenta llegar hasta Zelda sin llamar la atención. También es donde las ambiciones de Ganondorf amenazan directamente al reino. El lugar tiene peso político antes de que Link comprenda todo el plan."},
          Places, false},
    Entry{"graveyard", Kind::Place, {"Kakariko Graveyard", "Cementerio de Kakariko"},
          {"A burial ground holding pieces of Hyrule's royal past.",
           "Camposanto que conserva fragmentos del pasado de la familia real."},
          {"The composer brothers, royal tombs and the Sun's Song make it more than a gloomy side area. Its graves and paths hide entrances and clues. Visiting at different times can change which ghostly encounters appear.",
           "Los hermanos compositores, las tumbas reales y la Canción del Sol hacen de él algo más que una zona tenebrosa. Entre sus lápidas y senderos se esconden entradas y pistas. Visitarlo a distintas horas puede cambiar los encuentros fantasmales."},
          Places, false},
    Entry{"death_mountain_trail", Kind::Place, {"Death Mountain Trail", "Senda de la Montaña de la Muerte"},
          {"The steep route from Kakariko to the Gorons' mountain home.",
           "La subida empinada desde Kakariko hasta el hogar de los Goron."},
          {"Falling rocks, Tektites and side paths keep the ascent active. The trail leads toward Goron City, Dodongo Cavern and higher volcanic ground. It is an early lesson that reaching a destination can be a challenge in itself.",
           "Rocas que caen, Tektites y desvíos dan vida a la subida. La senda lleva a Ciudad Goron, la Caverna de los Dodongos y las alturas volcánicas. Enseña pronto que llegar a un destino puede ser un reto en sí mismo."},  // codespell:ignore ser
          Places, false},
    Entry{"death_mountain_crater", Kind::Place, {"Death Mountain Crater", "Cráter de la Montaña de la Muerte"},
          {"The hot volcanic summit above the Goron settlement.",
           "La cumbre volcánica y ardiente sobre el asentamiento Goron."},
          {"Lava and heat make lingering dangerous without suitable protection. This is more than the mountain's end point: it connects to later parts of Link's quest and reveals how far the region extends beneath its surface. Look for safe footing before taking a shortcut.",
           "La lava y el calor hacen peligroso quedarse sin protección adecuada. Es más que el final de la subida: conecta con etapas posteriores de la aventura y muestra cuánto se extiende la región bajo la superficie. Busca suelo firme antes de tomar un atajo."},
          Places, false},
    Entry{"zora_river", Kind::Place, {"Zora River", "Río Zora"},
          {"A winding water route leading toward Zora Domain.",
           "Curso de agua sinuoso que conduce al Dominio Zora."},
          {"The banks combine short platforming stretches with Octoroks and other river life. Following the river makes the Zora homeland feel like a place reached through exploration rather than a simple door on the map. Search its side paths for diversions.",
           "Las orillas combinan tramos de plataformas con Octoroks y otros habitantes del río. Seguirlo hace que el hogar Zora parezca un lugar descubierto explorando y no una simple puerta en el mapa. Sus desvíos esconden más cosas."},  // codespell:ignore hace
          Places, false},
    Entry{"zora_fountain", Kind::Place, {"Zora Fountain", "Fuente Zora"},
          {"The sheltered water behind Zora Domain, home to Lord Jabu-Jabu.",
           "El agua resguardada tras el Dominio Zora, hogar de Lord Jabu-Jabu."},
          {"The Zora revere the great creature, making the fountain both a location and a sacred space. Link's visit is connected to Ruto and the illness that troubles Jabu-Jabu. The nearby ice and water become important in later exploration.",
           "Los Zora veneran a la gran criatura, así que la fuente es un lugar físico y sagrado. La visita de Link está ligada a Ruto y a la enfermedad que sufre Jabu-Jabu. El hielo y el agua cercanos cobrarán importancia en otras exploraciones."},
          Places, false},
    Entry{"lake_hylia", Kind::Place, {"Lake Hylia", "Lago Hylia"},
          {"A broad lake at the edge of Hyrule's waterways.",
           "Gran lago en el extremo de los cursos de agua de Hyrule."},  // codespell:ignore cursos
          {"Fishing, a lakeside laboratory and hidden routes make it a place to revisit. Its connection to the Zora waters and the Water Temple gives it a role in both exploration and the main story. The lake's changing appearance shows how the kingdom responds to events elsewhere.",
           "La pesca, el laboratorio de la orilla y rutas ocultas invitan a volver. Su unión con las aguas Zora y el Templo del Agua le da un papel en la exploración y la historia principal. Su aspecto cambiante muestra cómo afectan al reino sucesos ocurridos lejos de allí."},
          Places, false},
    Entry{"gerudo_valley", Kind::Place, {"Gerudo Valley", "Valle Gerudo"},
          {"A dramatic crossing toward the Gerudo lands.",
           "Paso espectacular que conduce a las tierras gerudo."},
          {"Its bridge and river mark a clear transition from central Hyrule to a more guarded region. Reaching the fortress takes more than following the road, and the valley itself rewards a look around. The terrain foreshadows the harsher desert beyond.",
           "Su puente y río separan con claridad el centro de Hyrule de una región más vigilada. Llegar a la fortaleza exige algo más que seguir el camino; el propio valle merece explorarse. El terreno anticipa el desierto más duro que viene después."},
          Places, false},
    Entry{"mirage_desert", Kind::Place, {"Mirage Desert", "Desierto de los Espejismos"},
          {"A harsh, disorienting route beyond Gerudo Fortress.",
           "Ruta dura y desorientadora más allá de la Fortaleza Gerudo."},
          {"The desert tests navigation as much as combat: sand and poor visibility can erase an obvious route. Leevers emerge where Link lingers. Keep track of landmarks and prepare for the journey before leaving the safety of the fortress.",
           "El desierto pone a prueba la orientación tanto como el combate: arena y poca visibilidad borran la ruta evidente. Los Leevers salen donde Link se detiene. Fíjate en las referencias del terreno y prepárate antes de dejar atrás la fortaleza."},
          Places, false},
    Entry{"desert_colossus", Kind::Place, {"Desert Colossus", "Coloso del Desierto"},
          {"A monumental site beyond the Gerudo desert.",
           "Lugar monumental más allá del desierto gerudo."},
          {"Its giant figure and remote surroundings frame the approach to the Spirit Temple. The area has its own secrets and hostile wildlife, so the journey does not end when the building comes into view. Its scale gives the later quest an ancient, solemn tone.",
           "Su figura gigantesca y su aislamiento enmarcan la llegada al Templo del Espíritu. La zona guarda secretos y fauna hostil: el viaje no termina al ver el edificio. Su escala da a esta etapa de la aventura un aire antiguo y solemne."},
          Places, false},
    Entry{"hall_of_foes", Kind::Place, {"Hall of Fallen Foes", "Salón de los Enemigos Caídos"},
          {"A new dreamlike bestiary and rematch space in the Switch 2 remake.",
           "Nuevo bestiario onírico y espacio de revanchas del remake de Switch 2."},
          {"Defeated creatures gain statues with descriptions, main locations and useful items. Boss statues let players practice those fights again; the hall makes enemy knowledge part of the game itself. Kaichii's bestiary summarizes this material so it can be searched while playing.",
           "Las criaturas derrotadas adquieren estatuas con descripción, zonas principales y objetos útiles. Las estatuas de jefes permiten repetir combates; el Salón convierte el conocimiento de los enemigos en parte del juego. El bestiario de Kaichii resume ese material para poder buscarlo mientras juegas."},
          Places, false},
    Entry{"chamber_of_sages", Kind::Place, {"Chamber of Sages", "Cámara de los Sabios"},
          {"A sacred meeting place connected to the Sages.",
           "Lugar de reunión sagrado vinculado a los Sabios."},
          {"The chamber gives the awakened Sages a common space beyond the ordinary geography of Hyrule. It connects the heroes' individual temple stories to the wider effort against Ganondorf. Its significance becomes clearer as the adult part of the story progresses.",
           "La cámara da a los Sabios despiertos un espacio común fuera de la geografía corriente de Hyrule. Une las historias de cada templo con el esfuerzo conjunto contra Ganondorf. Su importancia se entiende mejor a medida que avanza la etapa adulta."},
          Places, true},
    Entry{"dodongo_cavern", Kind::Dungeon, {"Dodongo Cavern", "Caverna de los Dodongos"},
          {"A rocky cavern whose infestation threatens the Gorons' food supply.",
           "Caverna rocosa cuya infestación amenaza los alimentos de los Goron."},
          {"Bombs open blocked routes and are central to several fights. The Lizalfos pair teaches careful defense, while the giant Dodongo at the end turns the cavern's volcanic theme into a boss encounter. Darunia's concern explains why clearing it matters beyond Link's quest.",
           "Las bombas abren rutas bloqueadas y son esenciales en varios combates. La pareja de Lizalfos enseña a defenderse con paciencia; el Dodongo gigante del final convierte el tema volcánico en un jefe. La preocupación de Darunia explica por qué despejarla importa más allá de la misión de Link."},  // codespell:ignore varios
          Dungeons, false},
    Entry{"jabu_jabu_belly", Kind::Dungeon, {"Lord Jabu-Jabu's Belly", "Interior de Lord Jabu-Jabu"},
          {"A living dungeon inside the creature revered by the Zora.",  // codespell:ignore revered
           "Mazmorra viva dentro de la criatura venerada por los Zora."},
          {"Pulsing passages, electric jellyfish and strange parasites make it unlike the stone caverns before it. Ruto and the Spiritual Stone connect the exploration to the Zora story. The boomerang is particularly useful against the creatures found here.",
           "Pasillos palpitantes, medusas eléctricas y parásitos extraños la distinguen de las cavernas de piedra anteriores. Ruto y la Piedra Espiritual conectan la exploración con la historia Zora. El bumerán resulta especialmente útil contra sus criaturas."},
          Dungeons, false},
    Entry{"fire_temple", Kind::Dungeon, {"Fire Temple", "Templo del Fuego"},
          {"A volcanic temple tied to the fate of the Gorons.",
           "Templo volcánico ligado al destino de los Goron."},
          {"Its heat, lava and long vertical route force Link to manage both movement and combat. The Megaton Hammer changes how obstacles and certain enemies can be handled. Darunia's story gives urgency to the rooms beyond their puzzles.",
           "El calor, la lava y la larga ruta vertical obligan a cuidar tanto el movimiento como el combate. El Martillo Megatón cambia la forma de superar obstáculos y algunos enemigos. La historia de Darunia da urgencia a las salas más allá de sus puzles."},
          Dungeons, true},
    Entry{"water_temple", Kind::Dungeon, {"Water Temple", "Templo del Agua"},
          {"A submerged temple whose changing water levels reshape every route.",
           "Templo sumergido cuyos niveles de agua cambiantes rehacen cada ruta."},
          {"Solving it means revisiting rooms at different depths rather than just opening a straight chain of doors. The Iron Boots and Hookshot are important tools, and Ruto's story is tied to the place. Keep a mental map of where each water-level change opens a new path.",
           "Resolverlo exige volver a salas a distintas profundidades, no solo abrir una cadena de puertas. Las Botas de Hierro y el gancho son herramientas importantes, y la historia de Ruto está ligada al lugar. Conviene recordar qué ruta abre cada cambio del nivel de agua."},
          Dungeons, true},
    Entry{"shadow_temple", Kind::Dungeon, {"Shadow Temple", "Templo de las Sombras"},
          {"A dark temple built around hidden hazards and unsettling history.",
           "Templo oscuro basado en peligros ocultos y una historia inquietante."},
          {"Invisible paths and enemies make the Lens of Truth especially valuable. ReDeads, hands and other foes punish a rushed approach. Its imagery suggests a harsher side of Hyrule than the villages above ground reveal.",
           "Caminos y enemigos invisibles hacen especialmente valiosa la Lente de la Verdad. ReDeads, manos y otros adversarios castigan las prisas. Sus imágenes muestran un lado de Hyrule más duro que el visible en las aldeas de la superficie."},
          Dungeons, true},
    Entry{"spirit_temple", Kind::Dungeon, {"Spirit Temple", "Templo del Espíritu"},
          {"A desert temple whose routes involve both ages of Link.",
           "Templo del desierto cuyas rutas implican a Link niño y adulto."},
          {"Its architecture makes the time-travel idea tangible: one period can reach what the other cannot. Mirror Shield puzzles, Gerudo history and Iron Knuckle battles give it a distinct identity. The temple stands beyond the Desert Colossus, making the journey there part of its challenge.",
           "Su arquitectura vuelve tangible el viaje temporal: una edad alcanza lo que la otra no puede. Puzles del Escudo Espejo, historia gerudo y combates con Iron Knuckle le dan identidad propia. Está más allá del Coloso del Desierto; llegar hasta él también es parte del reto."},
          Dungeons, true},
    Entry{"bottom_of_well", Kind::Dungeon, {"Bottom of the Well", "Fondo del Pozo"},
          {"An underground labyrinth beneath Kakariko.",
           "Laberinto subterráneo bajo Kakariko."},
          {"Its false walls, hidden dangers and disturbing enemies turn observation into a survival skill. The Lens of Truth is the key reward associated with its secrets. It also prepares the player for the visual tricks of the Shadow Temple.",
           "Sus falsos muros, peligros ocultos y enemigos inquietantes convierten la observación en una habilidad de supervivencia. La Lente de la Verdad es la recompensa clave ligada a sus secretos. También prepara al jugador para los engaños visuales del Templo de las Sombras."},  // codespell:ignore visuales
          Dungeons, true},
    Entry{"ice_cavern", Kind::Dungeon, {"Ice Cavern", "Caverna de Hielo"},
          {"A frozen maze near Zora Fountain.", "Laberinto helado cerca de la Fuente Zora."},
          {"Freezards and icy paths make movement and positioning more difficult. The cavern offers tools needed to explore colder and deeper waters. Its setting also shows that the change affecting the Zora reaches beyond their settlement.",
           "Freezards y caminos helados complican el movimiento y la posición. La caverna ofrece herramientas necesarias para explorar aguas más frías y profundas. Su entorno muestra además que el cambio que afecta a los Zora va más allá de su asentamiento."},
          Dungeons, true},
    Entry{"gerudo_proving_grounds", Kind::Dungeon, {"Gerudo Proving Grounds", "Campo de Pruebas Gerudo"},
          {"An optional trial testing a broad range of Link's abilities.",
           "Prueba opcional que pone a examen muchas habilidades de Link."},
          {"The rooms mix combat, item use and navigation rather than following one temple's theme. Entering with a varied kit makes the challenges easier to understand. The reward makes the detour worthwhile for players who enjoy mastering the game's systems.",
           "Sus salas mezclan combate, uso de objetos y orientación en vez de seguir el tema de un solo templo. Entrar con equipo variado facilita entender los retos. La recompensa hace atractivo el desvío para quien disfrute dominando los sistemas del juego."},  // codespell:ignore hace
          Dungeons, true},
    Entry{"ganondorf_castle", Kind::Dungeon, {"Ganondorf's Castle", "Castillo de Ganondorf"},
          {"The final stronghold at the center of the adult-era conflict.",
           "Fortaleza final en el centro del conflicto de la era adulta."},
          {"Its challenges draw on the skills and items learned across Hyrule. The different sections recall earlier regions before the climb toward Ganondorf. Entering it is a culmination of the Sages' work, not just another dungeon on the map.",
           "Sus desafíos recuperan habilidades y objetos aprendidos por todo Hyrule. Las distintas secciones recuerdan regiones anteriores antes de subir hacia Ganondorf. Entrar en él culmina el trabajo de los Sabios, no es simplemente otra mazmorra del mapa."},
          Dungeons, true},
    Entry{"inside_ganondorf_castle", Kind::Dungeon, {"Inside Ganondorf's Castle", "Interior del castillo de Ganondorf"},
          {"The tower and inner route leading to the last confrontations.",
           "La torre y ruta interior que conducen a los últimos enfrentamientos."},
          {"Iron Knuckles and other demanding foes guard the ascent. The building's inner path narrows the adventure from a kingdom-wide journey to a direct confrontation. Be ready to use the equipment gathered throughout the game.",
           "Iron Knuckles y otros rivales exigentes guardan la subida. La ruta interior concentra una aventura por todo el reino en un enfrentamiento directo. Conviene preparar el equipo reunido durante el juego."},
          Dungeons, true},
};

} // namespace

std::span<const Entry> WorldEntries() {
    return Entries;
}

} // namespace GameCompanion
